/* Source: shared/lib/orders.js; syncTrackingDelivery. Generated by standalone-build.mjs. */
function syncTrackingDelivery(){
    const status=orderFulfilmentStatus();
    const stage=ORDER_STAGES[status];
    const delivered=status==='Delivered';
    if(delivered){
      revealDeliveryNotification();
      if(!flowState.csatDone && !flowState.csatDeliveryPrompted && document.querySelector('#tracking.active')){
        flowState.csatDeliveryPrompted=true;persistFlowState();
        const target=document.querySelector('.screen.active')?.id || 'tracking';
        requestAnimationFrame(()=>openCsatModal(target));
      }
    }
    const activeIndex=delivered ? ORDER_STEP_ORDER.length : ORDER_STEP_ORDER.indexOf(stage.active);
    const screen=document.getElementById('tracking');
    if(screen){
      screen.querySelectorAll('[data-track-step]').forEach(step => {
        const index=ORDER_STEP_ORDER.indexOf(step.dataset.trackStep);
        step.classList.toggle('done',index<activeIndex);
        step.classList.toggle('active',index===activeIndex);
      });
      // Keep the preparation step label consistent throughout tracking.
      const prepared=screen.querySelector('[data-track-step="prepared"] strong');
      if(prepared) prepared.textContent='กำลังจัดยา';
      const deliveredStep=screen.querySelector('[data-track-step="delivered"] strong');
      if(deliveredStep)deliveredStep.textContent=ORDER_STAGES.Delivered.label;
      /* Client, 23 Sep: the two ends of the journey carry a time — when the
         money was taken, and when the parcel arrives. The paid stamp is the
         moment of payment; a deep-linked demo has never been through checkout,
         so the first visit fixes one shortly before now and keeps it rather
         than moving the time on every render. The last step shows the arrival
         window's end until the order is delivered, then the delivered stamp. */
      const paidTime=screen.querySelector('[data-track-time="paid"]');
      if(paidTime){
        if(!flowState.orderState.paidAt){
          flowState.orderState.paidAt=Date.now()-25*60000;
          persistFlowState();
        }
        paidTime.textContent=clockStamp(new Date(flowState.orderState.paidAt));
      }
      const deliveredTime=screen.querySelector('[data-track-time="delivered"]');
      if(deliveredTime){
        /* Until it arrives this is the end of the arrival window, with a tilde
           marking it as the estimate it is — a word there would have to be
           translated and would wrap the 10px column onto two lines. Arrival stamps the order once and then reads back, so
           the time the patient saw on the day is the time they see later. */
        if(delivered && !flowState.orderState.deliveredAt){
          flowState.orderState.deliveredAt=Date.now();
          persistFlowState();
        }
        deliveredTime.textContent=delivered
          ? clockStamp(new Date(flowState.orderState.deliveredAt))
          : '~'+deliveryArrivalWindow().split(' - ').pop();
      }
      const hint=screen.querySelector('[data-track-step="delivered"] .hint');
      /* A step that says it is finished should say when, in the same format
         as the paid step above it (client, 13 Sep). */
      if(hint) hint.textContent=delivered ? 'ได้รับแล้ว · '+new Date(flowState.orderState.deliveredAt).toLocaleString(document.documentElement.lang==='th' ? 'th-TH' : 'en-GB',{day:'2-digit',month:'2-digit',year:'2-digit',hour:'2-digit',minute:'2-digit'}) : 'รอดำเนินการ';
      // Receipt can only be confirmed while the order is actually on its way.
      const confirmButton=screen.querySelector('[data-delivery-confirm]');
      if(confirmButton) confirmButton.hidden=stage.active!=='out';
    }
    document.querySelectorAll('[data-order-progress-badge]').forEach(badge => {
      badge.textContent=stage.label;
      badge.className='badge badge--'+stage.tone;
    });
    /* The bar reads the same stage the badge does. A null active stage is
       delivered, so every segment is behind the patient. */
    const orderSteps=['prepared','dispatch','out','delivered'];
    const at=stage.active ? orderSteps.indexOf(stage.active) : orderSteps.length;
    document.querySelectorAll('[data-order-progress] [data-order-step]').forEach(step => {
      const index=orderSteps.indexOf(step.dataset.orderStep);
      step.classList.toggle('is-done',index<at);
      step.classList.toggle('is-current',index===at);
    });
    document.querySelectorAll('[data-order-progress]').forEach(bar => {
      if(bar.closest('#activity')) bar.hidden=delivered;
      const thaiLabel='ความคืบหน้าคำสั่งซื้อ · '+stage.label;
      const englishStage={prepared:'dispensing',dispatch:'rider collecting your order',out:'out for delivery'}[stage.active] || 'delivered';
      // Dynamic accessibility copy must use the current language immediately;
      // waiting for the translation observer leaves a Thai label for one frame.
      bar.removeAttribute('data-al-th');
      bar.dataset.progressLabelTh=thaiLabel;
      bar.dataset.progressLabelEn='Order progress · '+englishStage;
      bar.setAttribute('aria-label',document.documentElement.lang==='th' ? thaiLabel : bar.dataset.progressLabelEn);
    });
    document.querySelectorAll('[data-order-progress-note]').forEach(note => { note.textContent=stage.note; });
    const charge=orderChargeSummary();
    document.querySelectorAll('[data-order-total]').forEach(amount => { amount.textContent=baht(charge.total); });
    syncTrackingDetails(delivered);
    if(goldenOrderSnapshot()) syncPostPaymentPanels();
  }

/* Source: shared/lib/orders.js; syncPostPaymentPanels. Generated by standalone-build.mjs. */
function syncPostPaymentPanels(){
    const charge=orderChargeSummary();
    const methodKey=flowState.orderState.paidMethod || flowState.orderState.paymentMethod || 'qr';
    const method=PAYMENT_METHOD_LABELS[methodKey] || 'QR Code';
    const discount=Math.max(0,charge.credit+charge.promo);
    const address=goldenOrderSnapshot()?.order.address || (flowState.orderState.addressConfirmed ? deliveryAddressSummary() : 'ยังไม่ได้เลือกที่อยู่จัดส่ง');
    const courier=charge.method==='pickup' ? 'รับที่ร้านขายยา' : (charge.method==='postal' ? 'ไปรษณีย์ไทย' : 'Lalamove');
    const instruction=String(flowState.orderState.address?.note || '').trim() || 'โทรก่อนถึงและวางไว้ที่ล็อบบี้';
    const snapshotItems=selectedOrderSnapshotItems();
    setPostpayText('[data-postpay-method]',method);
    setPostpayText('[data-postpay-total]',baht(charge.total));
    setPostpayText('[data-postpay-subtotal]',baht(charge.subtotal+charge.addon+charge.consultationCharged));
    setPostpayText('[data-postpay-delivery]',charge.delivery ? baht(charge.delivery) : 'ฟรี');
    setPostpayText('[data-postpay-discount]','− '+baht(discount));
    setPostpayHidden('[data-postpay-discount-row]',discount<=0);
    setPostpayText('[data-postpay-arrival]',deliveryArrivalWindow());
    setPostpayText('[data-postpay-address]',address);
    setPostpayText('[data-postpay-courier]',courier);
    setPostpayText('[data-postpay-instruction]',instruction);
    setPostpayText('[data-postpay-item-count]',`${snapshotItems.length} รายการ`);
    /* The count and preview come from the same basket. The old markup always
       showed two medicine photos even when the order said three items. Clone
       the checkout photos for every selected line item, including add-ons. */
    renderPostpaySnapshotThumbnails(snapshotItems);
  }

/* Source: shared/lib/ui.js; clockStamp. Generated by standalone-build.mjs. */
function clockStamp(date){
    return String(date.getHours()).padStart(2,'0')+':'+String(date.getMinutes()).padStart(2,'0');
  }

/* Source: shared/lib/orders.js; deliveryArrivalWindow. Generated by standalone-build.mjs. */
function deliveryArrivalWindow(){
    const minutes=flowState.orderState.deliveryMethod==='postal' ? 24*60 : 95;
    const from=new Date(Date.now()+(minutes-40)*60000);
    const to=new Date(Date.now()+minutes*60000);
    const clock=d => String(d.getHours()).padStart(2,'0')+':'+String(d.getMinutes()).padStart(2,'0');
    return clock(from)+' - '+clock(to);
  }

/* Source: shared/lib/orders.js; orderChargeSummary. Generated by standalone-build.mjs. */
function orderChargeSummary(){
    const golden=goldenOrderSnapshot();
    if(golden) return {method:'same-day',subtotal:golden.treatment.medicineFee,addon:0,delivery:golden.order.deliveryFee,credit:0,promo:0,total:golden.order.total,consultationCharged:0};
    const pickup=flowState.orderState.fulfillmentMode==='pickup';
    const method=pickup ? 'pickup' : (flowState.orderState.paidDeliveryMethod || flowState.orderState.deliveryMethod || 'same-day');
    const subtotal=medicineSubtotal();
    const addon=selectedAddOnTotal();
    const delivery=hasFulfillableItems() && !pickup ? deliveryFeeFor(method) : 0;
    const credit=Math.min(subtotal,partnerMedicineCoverageCredit());
    const promo=appliedPromo ? Math.max(0,Number(appliedPromo.amount) || 0) : 0;
    const goods=subtotal+addon+delivery-credit;
    const recorded=Number(flowState.orderState.paidAmount);
    const total=flowState.orderState.paidAmount!=null && Number.isFinite(recorded)
      ? Math.max(0,recorded)
      : Math.max(0,consultationBalanceDue()+goods-promo);
    const consultationCharged=flowState.orderState.checkoutOrigin==='refill'
      ? 0
      : Math.max(0,Math.min(CONSULTATION_FEE_BAHT,total+promo-goods));
    return {method,subtotal,addon,delivery,credit,promo,total,consultationCharged};
  }

/* Source: shared/lib/clinical.js; syncTrackingDetails. Generated by standalone-build.mjs. */
function syncTrackingDetails(delivered){
    const screen=document.getElementById('tracking');
    if(!screen) return;
    const golden=goldenOrderSnapshot();
    const pickup=!golden && flowState.orderState.fulfillmentMode==='pickup';
    const state=screen.querySelector('[data-delivery-eta-state]');
    const windowEl=screen.querySelector('[data-delivery-eta-window]');
    const label=screen.querySelector('.delivery-eta__label');
    const outForDelivery=screen.querySelector('[data-track-step="out"]')?.classList.contains('active');
    const preparing=screen.querySelector('[data-track-step="prepared"]')?.classList.contains('active');
    if(label) label.textContent=delivered ? 'ส่งถึงเมื่อ' : (pickup ? 'รับได้ประมาณ' : 'ถึงประมาณ');
    screen.querySelector('.delivery-eta')?.classList.toggle('is-delivered',Boolean(delivered));
    /* The card is scanned, not read: one clause each. */
    if(state){
      state.textContent=delivered
        ? 'จัดส่งสำเร็จ'
        : pickup
          ? 'รับยาได้ที่ร้าน'
          : outForDelivery
            ? 'กำลังจัดส่ง'
            : orderFulfilmentStatus()==='Rider pickup'
              ? 'กำลังจัดส่ง'
            : preparing
              ? 'กำลังจัดยา'
              : 'กำลังจัดส่ง';
    }
    if(windowEl) windowEl.textContent=delivered ? clockStamp(new Date(flowState.orderState.deliveredAt || Date.now())) : deliveryArrivalWindow();
    /* Reached from an activity card rather than through the address step, the
       row read "no delivery address chosen" on an order already on the road.
       An empty address is a missing fact, so the row goes rather than states it. */
    const address=screen.querySelector('[data-delivery-address]');
    const hasAddress=Boolean(golden || flowState.orderState.addressConfirmed);
    if(address && hasAddress) address.textContent=golden?.order.address || deliveryAddressSummary();
    if(golden){
      screen.querySelector('[data-delivery-recipient]').textContent=golden.patient.name;
      const phone=screen.querySelector('[data-delivery-recipient-phone]');
      if(phone){phone.textContent=golden.patient.phone;phone.removeAttribute('href');}
    }
    screen.querySelectorAll('[data-delivery-courier]').forEach(courier => {
      courier.textContent=!golden && flowState.orderState.deliveryMethod==='postal' ? 'ไปรษณีย์ไทย' : 'Lalamove';
    });
    // The courier rows are meaningless for a counter pickup.
    screen.querySelectorAll('[data-delivery-courier],[data-delivery-address]').forEach(el => {
      const fact=el.closest('.delivery-fact');
      if(!fact) return;
      fact.hidden = pickup || (el.hasAttribute('data-delivery-address') && !hasAddress);
    });
    /* Same-day and postal are two different deliveries, and the screen was
       showing both: a rider with a live position and a Thailand Post tracking
       number for the same order. A parcel number belongs to the postal one, a
       named rider to the same-day one, and only one of them is ever true. */
    const postal=!golden && !pickup && flowState.orderState.deliveryMethod==='postal';
    const deliveryIcon=screen.querySelector('[data-track-step="out"] use');
    if(deliveryIcon) deliveryIcon.setAttribute('href',postal ? '#krane-delivery-truck' : '#krane-delivery-motorcycle');
    const parcelCard=screen.querySelector('[data-tracking-reference]');
    if(parcelCard) parcelCard.hidden=!postal;
    /* Rendered from the order, not written into the markup, so it always shows
       what was actually paid for including anything declined at checkout. */
    const items=document.querySelector('#order-summary [data-delivery-items]');
    if(items){
      const charge=orderChargeSummary();
      const rows=[];
      /* The list reads like the receipt: every line this order involved, then
         the one amount it charged, which is the same amount the activity card
         shows. The consultation leads it the way it leads checkout; when it was
         settled before this payment, or a plan covered it, the line says so
         rather than adding to the total (client, 13 and 14 Sep). */
      const consultationRow=document.querySelector('#payment [data-order-consultation]');
      if(consultationRow && flowState.orderState.checkoutOrigin!=='refill'){
        const covered=Math.max(0,Math.min(CONSULTATION_FEE_BAHT,Number(flowState.coverage?.consultationCredit || 0)));
        rows.push({
          name:consultationRow.querySelector('.checkout-order__name')?.textContent || 'ค่าปรึกษาแพทย์',
          description:consultationRow.querySelector('.checkout-order__note')?.textContent || '',
          quantity:charge.consultationCharged>0 ? '1 ครั้ง' : (covered ? 'อยู่ในสิทธิ์' : 'ชำระแล้วตอนปรึกษา'),
          price:charge.consultationCharged,
          priceText:charge.consultationCharged ? '' : '฿ 0',
          icon:consultationRow.querySelector('.checkout-order__thumb')
        });
      }
      Object.entries(MEDICINE_PRICES).forEach(([key,unit]) => {
        const quantity=Math.max(0,Number(flowState.orderState.quantities[key] || 0));
        if(!quantity) return;
        const paymentRow=document.querySelector(`#payment [data-order-item="${key}"]`);
        const name=paymentRow?.querySelector('.checkout-order__name')?.textContent || key;
        const description=paymentRow?.querySelector('.checkout-order__note')?.textContent || '';
        const photo=paymentRow?.querySelector('.checkout-order__thumb img')?.getAttribute('src') || '';
        rows.push({name,description,quantity:quantity+' แผง',price:unit*quantity,photo});
      });
      Object.entries(ADDON_PRICES).forEach(([key,price]) => {
        const quantity=Math.max(0,Math.min(10,Number(flowState.orderState.addonQuantities[key] || 0)));
        if(!quantity) return;
        const paymentRow=document.querySelector(`#payment [data-order-addon="${key}"]`);
        const name=paymentRow?.querySelector('.checkout-order__name')?.textContent || key;
        const description=paymentRow?.querySelector('.checkout-order__note')?.textContent || '';
        const photo=paymentRow?.querySelector('.checkout-order__thumb img')?.getAttribute('src') || '';
        rows.push({name,description,quantity:quantity+' ชิ้น',price:price*quantity,photo});
      });
      if(hasFulfillableItems()){
        const courierIcon=screen.querySelector('[data-delivery-courier]')?.closest('.delivery-fact')?.querySelector('.delivery-fact__icon');
        rows.push({
          name:charge.method==='pickup' ? 'รับยาที่ร้าน' : 'ค่าจัดส่ง',
          description:charge.method==='pickup' ? 'ร้านยาฟาสซิโน' : charge.method==='postal' ? 'ไปรษณีย์ไทย' : 'Lalamove ภายในวัน',
          quantity:'',
          price:charge.delivery,
          priceText:charge.delivery ? '' : 'ฟรี',
          icon:courierIcon
        });
      }
      if(charge.credit) rows.push({name:'สิทธิ์ประกันค่ายา',description:'',quantity:'',price:-charge.credit});
      if(charge.promo) rows.push({name:'ส่วนลด',description:appliedPromo?.code || '',quantity:'',price:-charge.promo});
      if(golden){
        rows.splice(0,rows.length,...golden.treatment.medicines.map(item=>({name:item.name,description:item.dosage,quantity:item.quantity ? String(item.quantity) : '',price:item.price})),{name:'ค่าจัดส่ง',description:'Lalamove',quantity:'',price:golden.order.deliveryFee});
      }
      items.replaceChildren(...rows.map(row => {
        const line=document.createElement('div');
        // A credit or a discount has no picture, so it takes the two-column row.
        line.className=row.photo || row.icon ? 'delivery-item' : 'delivery-item delivery-item--adjust';
        if(row.photo){
          const thumb=document.createElement('span');
          thumb.className='delivery-item__thumb';
          thumb.setAttribute('aria-hidden','true');
          const image=document.createElement('img');
          image.src=row.photo;
          image.alt='';
          image.loading='lazy';
          image.decoding='async';
          thumb.append(image);
          line.append(thumb);
        }
        else if(row.icon){
          const thumb=document.createElement('span');
          thumb.className='delivery-item__thumb delivery-item__thumb--service';
          thumb.append(...row.icon.cloneNode(true).childNodes);
          line.append(thumb);
        }
        const body=document.createElement('span');
        body.className='delivery-item__body';
        const name=document.createElement('span');
        name.className='delivery-item__name';
        name.textContent=row.name;
        const description=document.createElement('span');
        description.className='delivery-item__description';
        description.textContent=row.description;
        body.append(name,description);
        const meta=document.createElement('span');
        meta.className='delivery-item__meta';
        const price=document.createElement('span');
        price.className='delivery-item__price';
        price.textContent=row.priceText || (row.price<0 ? '−'+baht(-row.price) : baht(row.price));
        const quantity=document.createElement('span');
        quantity.className='delivery-item__quantity';
        quantity.textContent=row.quantity;
        meta.append(price,quantity);
        line.append(body,meta);
        return line;
      }));
      if(rows.length){
        const foot=document.createElement('div');
        foot.className='delivery-item delivery-item--total';
        const label=document.createElement('span');
        label.className='delivery-item__name';
        label.textContent='ยอดชำระ';
        const price=document.createElement('span');
        price.className='delivery-item__price';
        price.textContent=baht(charge.total);
        foot.append(label,price);
        items.append(foot);
        /* Client, 5 Oct: the list already names every line and the amount, so
           the "สรุปการชำระเงิน" card under it was the same three numbers a
           second time. The one thing it said that the list did not is how the
           order was paid, which belongs with the amount it paid. */
        const method=document.createElement('div');
        method.className='delivery-item delivery-item--method';
        const methodLabel=document.createElement('span');
        methodLabel.className='delivery-item__name';
        methodLabel.textContent='ชำระด้วย';
        const methodValue=document.createElement('span');
        methodValue.className='delivery-item__price';
        methodValue.textContent=screen.querySelector('[data-postpay-method]')?.textContent?.trim()
          || document.querySelector('#payment [data-payment-method]')?.textContent?.trim() || 'QR Code';
        method.append(methodLabel,methodValue);
        items.append(method);
      }
      items.closest('.stack-2').hidden=!rows.length;
    }
    const recipient=screen.querySelector('[data-delivery-recipient]');
    const recipientPhone=screen.querySelector('[data-delivery-recipient-phone]');
    const savedName=String(flowState.orderState.address.recipientName || flowState.patientName || '').trim();
    const savedPhone=String(flowState.orderState.address.recipientPhone || flowState.verifiedPhone || '').trim();
    if(recipient && savedName) recipient.textContent=savedName;
    if(recipientPhone && savedPhone){
      recipientPhone.textContent=formatThaiPhone(savedPhone);
      recipientPhone.href='tel:+66'+normalizePhone(savedPhone).replace(/^0/,'');
    }
    const recipientFact=recipientPhone?.closest('.delivery-fact');
    // Who it is going to still matters when it is going by post.
    if(recipientFact) recipientFact.hidden=pickup;
    /* The rider only exists once the order has left the pharmacy, and never for
       post or a counter pickup. */
    const riderLine=screen.querySelector('[data-track-rider]');
    if(riderLine){
      const outStep=screen.querySelector('[data-track-step="out"]');
      const onTheRoad=Boolean(outStep && (outStep.classList.contains('active') || outStep.classList.contains('done')));
      riderLine.hidden=pickup || postal || !onTheRoad;
    }
    const riderButton=screen.querySelector('[data-rider-locate]');
    if(riderButton) riderButton.hidden=pickup || postal || !outForDelivery;
  }

/* Source: shared/lib/orders.js; goldenOrderSnapshot. Generated by standalone-build.mjs. */
function goldenOrderSnapshot(){
    if(new URLSearchParams(location.search).get('demoOrder')!=='golden') return null;
    const demo=window.KraneGoldenDemo,fixture=demo?.fixture,prescription=demo?.readState().prescription;
    if(!fixture || !prescription) return fixture || null;
    return {...fixture,treatment:{...fixture.treatment,medicines:prescription.items.map(item=>({name:item.name,dosage:item.directions || item.dirTH || item.dir || '',price:item.price*item.qty,quantity:item.qty})),medicineFee:prescription.total},order:{...fixture.order,total:prescription.total+fixture.order.deliveryFee}};
  }

/* Source: shared/lib/orders.js; selectedOrderSnapshotItems. Generated by standalone-build.mjs. */
function selectedOrderSnapshotItems(){
    const golden=goldenOrderSnapshot();
    if(golden) return golden.treatment.medicines.map((item,index)=>({key:'golden-'+index,quantity:item.quantity || 1,imageSource:''}));
    const items=[];
    const collect=(quantities,itemAttribute) => {
      Object.entries(quantities || {}).forEach(([key,value]) => {
        const quantity=Number(value);
        if(quantity<=0) return;
        const image=document.querySelector(`#payment [${itemAttribute}="${key}"] img`);
        items.push({key,quantity,imageSource:image?.getAttribute('src') || ''});
      });
    };
    collect(flowState.orderState.quantities,'data-order-item');
    collect(flowState.orderState.addonQuantities,'data-order-addon');
    return items;
  }

/* Source: shared/lib/ui.js; setPostpayText. Generated by standalone-build.mjs. */
function setPostpayText(selector,value){
    document.querySelectorAll(selector).forEach(node => { node.textContent=value; });
  }

/* Source: shared/lib/ui.js; setPostpayHidden. Generated by standalone-build.mjs. */
function setPostpayHidden(selector,hidden){
    document.querySelectorAll(selector).forEach(node => { node.hidden=hidden; });
  }

/* Source: shared/lib/ui.js; renderPostpaySnapshotThumbnails. Generated by standalone-build.mjs. */
function renderPostpaySnapshotThumbnails(items){
    const sources=items.map(item => item.imageSource).filter(Boolean);
    const previewSources=sources.slice(0,POSTPAY_THUMBNAIL_LIMIT);
    const remaining=sources.length-previewSources.length;
    document.querySelectorAll('.postpay-order-snapshot__thumbs').forEach(container => {
      const previewImages=previewSources.map(createPostpayThumbnail);
      container.replaceChildren(...previewImages,...(remaining ? [createPostpayThumbnailOverflow(remaining)] : []));
      container.hidden=sources.length===0;
    });
  }

/* Source: shared/lib/ui.js; createPostpayThumbnail. Generated by standalone-build.mjs. */
function createPostpayThumbnail(source){
    const image=document.createElement('img');
    image.src=source;
    image.alt='';
    image.loading='lazy';
    image.decoding='async';
    return image;
  }
